 // Bank CSV imports are staged; importing a statement never posts a second copy of a payment.
 app.post(base+'/bank-imports',finance,wrap(async(req,res)=>{
  const csv=String(req.body&&req.body.csv||''),name=String(req.body&&req.body.fileName||'bank-statement.csv').slice(0,180);if(!csv||csv.length>2*1024*1024)return res.status(400).json({ok:false,message:'Upload a CSV file up to 2 MB.'});
  const rows=parseCsv(csv);if(rows.length<2)return res.status(400).json({ok:false,message:'The CSV must include a header and at least one transaction row.'});
  const headers=rows.shift().map(x=>String(x).trim().toLowerCase().replace(/[ _-]+/g,''));
  const col=(...names)=>headers.findIndex(x=>names.includes(x));const di=col('date','transactiondate','valuedate'),ai=col('amount','credit','creditamount'),ri=col('reference','transactionreference','receipt','transactionid'),li=col('accountreference','rentaccount','account'),xi=col('description','details','narration');
  if([di,ai,ri].some(x=>x<0))return res.status(400).json({ok:false,message:'CSV headers must include date, amount/credit and reference/transaction ID. Optional: account_reference and description.'});
  const imp=(await pool.query('INSERT INTO rent_bank_imports(file_name,row_count,imported_by) VALUES($1,$2,$3) RETURNING *',[name,rows.length,actor(req).id])).rows[0];let imported=0,invalid=0;
  for(const row of rows){const date=csvDate(row[di]),amount=Number(String(row[ai]||'').replace(/[ ,]/g,'')),ref=String(row[ri]||'').trim(),account=li>=0?String(row[li]||'').trim().toUpperCase():null,desc=xi>=0?String(row[xi]||'').trim():null;if(!date||!money(amount)||!ref){invalid++;continue;}
   const existing=(await pool.query('SELECT id FROM rent_payments WHERE mpesa_receipt=$1 OR external_reference=$1 LIMIT 1',[ref])).rows[0];const lease=account?(await pool.query('SELECT id FROM rent_leases WHERE rent_account_ref=$1 ORDER BY created_at DESC LIMIT 1',[account])).rows[0]:null;
   await pool.query(`INSERT INTO rent_bank_statement_lines(import_id,transaction_date,amount,reference,account_reference,description,status,matched_payment_id,matched_lease_id)
    VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(import_id,reference,amount) DO NOTHING`,[imp.id,date,amount,ref,account,desc,existing?'duplicate':lease?'matched':'unmatched',existing&&existing.id||null,lease&&lease.id||null]);imported++;
  }
  await audit(pool,req,'RENT_BANK_STATEMENT_IMPORTED',{importId:imp.id,fileName:name,rows:imported,invalid});res.status(201).json({ok:true,importId:imp.id,imported,invalid});
 }));
