 // Arrears ageing is based on the live outstanding charge balance, not total historical billing.
 app.get(base+'/reports/ageing',managerFinance,wrap(async(req,res)=>{const property=String(req.query.propertyId||''),unit=String(req.query.unitId||''),from=String(req.query.from||'2000-01-01'),to=String(req.query.to||today());if(!validDate(from)||!validDate(to)||from>to)return res.status(400).json({ok:false,message:'Invalid report date range.'});const rows=(await pool.query(`SELECT l.id lease_id,l.tenant_name,l.unit_label,l.rent_account_ref,p.name property_name,
  COALESCE(sum(c.amount-COALESCE(a.paid,0)) FILTER(WHERE $2::date-c.due_date BETWEEN 0 AND 30),0)::bigint days_0_30,
  COALESCE(sum(c.amount-COALESCE(a.paid,0)) FILTER(WHERE $2::date-c.due_date BETWEEN 31 AND 60),0)::bigint days_31_60,
  COALESCE(sum(c.amount-COALESCE(a.paid,0)) FILTER(WHERE $2::date-c.due_date BETWEEN 61 AND 90),0)::bigint days_61_90,
  COALESCE(sum(c.amount-COALESCE(a.paid,0)) FILTER(WHERE $2::date-c.due_date>90),0)::bigint days_over_90,
  COALESCE(sum(c.amount-COALESCE(a.paid,0)),0)::bigint total_due,min(c.due_date) oldest_due
 FROM rent_leases l JOIN rent_charges c ON c.lease_id=l.id AND c.voided_at IS NULL LEFT JOIN property_units u ON u.id=l.property_unit_id LEFT JOIN properties p ON p.id=u.property_id
 LEFT JOIN (SELECT charge_id,sum(amount) paid FROM rent_allocations WHERE reversed_at IS NULL GROUP BY charge_id) a ON a.charge_id=c.id
 WHERE c.voided_at IS NULL AND c.due_date<$2::date AND c.due_date BETWEEN $1::date AND $2::date AND c.amount>COALESCE(a.paid,0) AND ($3='' OR p.id::text=$3) AND ($4='' OR u.id::text=$4)
 GROUP BY l.id,p.id ORDER BY total_due DESC`,[from,to,property,unit])).rows;res.json({ok:true,from,to,items:rows,totals:rows.reduce((a,x)=>{for(const k of ['days_0_30','days_31_60','days_61_90','days_over_90','total_due'])a[k]=(a[k]||0)+Number(x[k]);return a;},{})});}));

 app.get(base+'/reports/ageing.csv',managerFinance,wrap(async(req,res)=>{const property=String(req.query.propertyId||''),unit=String(req.query.unitId||''),from=String(req.query.from||'2000-01-01'),to=String(req.query.to||today());if(!validDate(from)||!validDate(to)||from>to)return res.status(400).send('Invalid report date range.');const rows=(await pool.query(`SELECT p.name property_name,l.tenant_name,l.unit_label,l.rent_account_ref,c.period_start,c.due_date,c.amount,COALESCE(a.paid,0)::int paid,(c.amount-COALESCE(a.paid,0))::int balance,($2::date-c.due_date)::int days_overdue FROM rent_leases l JOIN rent_charges c ON c.lease_id=l.id AND c.voided_at IS NULL LEFT JOIN property_units u ON u.id=l.property_unit_id LEFT JOIN properties p ON p.id=u.property_id LEFT JOIN (SELECT charge_id,sum(amount) paid FROM rent_allocations WHERE reversed_at IS NULL GROUP BY charge_id) a ON a.charge_id=c.id WHERE c.due_date<$2::date AND c.due_date BETWEEN $1::date AND $2::date AND c.amount>COALESCE(a.paid,0) AND ($3='' OR p.id::text=$3) AND ($4='' OR u.id::text=$4) ORDER BY c.due_date,l.unit_label`,[from,to,property,unit])).rows;const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[['Property','Tenant','Unit','Rent account','Period start','Due date','Charged KSh','Paid KSh','Balance KSh','Days overdue'],...rows.map(x=>[x.property_name,x.tenant_name,x.unit_label,x.rent_account_ref,x.period_start,x.due_date,x.amount,x.paid,x.balance,x.days_overdue])].map(row=>row.map(cell).join(',')).join('\r\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="mauriskade-arrears-ageing-'+from+'-'+to+'.csv"');res.send('\uFEFF'+csv);}));

