 // Dashboard additions: previous-period arrears recovered, deposits and property occupancy.
 app.get(base+'/reports/extended',managerFinance,wrap(async(_req,res)=>{
  const month=(await pool.query(`SELECT date_trunc('month',now() AT TIME ZONE 'Africa/Nairobi')::date month_start`)).rows[0].month_start;
  const recovered=(await pool.query(`SELECT COALESCE(sum(a.amount),0)::bigint amount FROM rent_allocations a JOIN rent_charges c ON c.id=a.charge_id JOIN rent_payments p ON p.id=a.payment_id WHERE a.reversed_at IS NULL AND c.voided_at IS NULL AND p.status IN ('confirmed','allocated') AND p.method<>'credit_adjustment' AND p.transaction_time >= $1::date AND c.due_date<$1::date`,[month])).rows[0].amount;
  const cash=(await pool.query("SELECT COALESCE(sum(amount),0)::bigint amount FROM rent_payments WHERE status IN ('confirmed','allocated') AND method<>'credit_adjustment' AND COALESCE(transaction_time,created_at)>=date_trunc('month',now() AT TIME ZONE 'Africa/Nairobi')")).rows[0].amount;
  const deposits=(await pool.query("SELECT COALESCE(sum(CASE WHEN kind IN ('received','transfer_in') THEN amount WHEN kind IN ('deduction','transfer_out') THEN -amount WHEN kind='refund' AND status='paid' THEN -amount ELSE 0 END),0)::bigint balance FROM rent_deposit_transactions")).rows[0].balance;
  res.json({ok:true,priorArrearsRecovered:Number(recovered),cashReceived:Number(cash),depositLiability:Number(deposits)});
 }));

