  await pool.query('UPDATE rent_communication_log SET status=$2,delivered_at=CASE WHEN $2=\'delivered\' THEN now() ELSE delivered_at END,provider_response=provider_response||$3::jsonb WHERE provider_reference=$1',[ref,status,JSON.stringify(req.body)]);
